 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Each solid 3x3 square emits horizontal and vertical rays through its center.
    objs = []
    for r in range(h-2):
        for c in range(w-2):
            block = [grid[y][c:c+3] for y in range(r,r+3)]
            colors = {v for row in block for v in row}
            if len(colors)==1 and 0 not in colors:
                color=next(iter(colors))
                if (r==0 or c==0 or True):
                    # only detect blocks with a color repeated as solid 3x3
                    objs.append((r+1,c+1,color))
    # Remove duplicate detections (a uniform 3x3 has only one top-left in principle).
    objs=list(dict.fromkeys(objs))
    rays=[]
    for r,c,color in objs:
        rays.extend([(r,x,color) for x in range(w) if x not in range(c-1,c+2)])
        rays.extend([(y,c,color) for y in range(h) if y not in range(r-1,r+2)])
    # Extend ray through all cells, except crossings between rays of different objects/colors,
    # which remain blank. The blocks themselves stay intact.
    for r,c,color in rays:
        if grid[r][c]==0:
            out[r][c]=color
    for i,(r,c,col) in enumerate(rays):
        for rr,cc,other in rays[i+1:]:
            if rr==r and cc==c and col!=other:
                out[r][c]=0
    return out
"
